  // IATA-style aliases that do not share a 3-letter suffix with the IEM sid.
  var ALIAS = { SJU: "TJSJ", STT: "TIST", STX: "TISX", GUM: "PGUM", SPN: "PGSN", PPG: "NSTU", HNL: "PHNL", OGG: "PHOG", KOA: "PHKO", LIH: "PHLI", ANC: "PANC", FAI: "PAFA", JNU: "PAJN" };
